#include "juno6.h"
#include <math.h>
#include <string.h>
#define PI 3.14159265358979323846f
#define TWO_PI 6.28318530717958647692f
static float clampf(float x,float a,float b){return x<a?a:x>b?b:x;}
static float midi_hz(unsigned n){return 440.0f*powf(2.0f,((float)n-69.0f)/12.0f);}
static float blep(float t,float dt){if(t<dt){t/=dt;return t+t-t*t-1.0f;}if(t>1.0f-dt){t=(t-1.0f)/dt;return t*t+t+t+1.0f;}return 0.0f;}
void juno6_init(juno6_t*s,float sr){memset(s,0,sizeof *s);s->sample_rate=sr>8000?sr:44100;s->attack=.008f;s->decay=.28f;s->sustain=.72f;s->release=.24f;s->cutoff=.68f;s->resonance=.12f;s->pulse_width=.5f;s->sub_level=.22f;}
int juno6_note_on(juno6_t*s,uint8_t note,uint8_t vel){unsigned i,chosen=0;uint32_t oldest;if(!vel){juno6_note_off(s,note);return 1;}for(i=0;i<6;i++)if(s->voice[i].gate&&s->voice[i].note==note)goto assign;for(i=0;i<6;i++)if(!s->voice[i].gate&&s->voice[i].envelope<.0001f){chosen=i;goto assign;}for(i=0;i<6;i++)if(!s->voice[i].gate){chosen=i;goto assign;}oldest=s->voice[0].age;for(i=1;i<6;i++)if(s->voice[i].age<oldest){oldest=s->voice[i].age;chosen=i;}assign:{juno6_voice_t*v=&s->voice[chosen];v->note=note;v->gate=1;v->stage=1;v->age=++s->age;v->increment=midi_hz(note)/s->sample_rate;v->velocity=(float)vel/127.0f;if(v->envelope<.0001f)v->phase=0;}return 1;}
void juno6_note_off(juno6_t*s,uint8_t note){unsigned i;for(i=0;i<6;i++)if(s->voice[i].gate&&s->voice[i].note==note){s->voice[i].gate=0;s->voice[i].stage=4;}}
void juno6_all_off(juno6_t*s){unsigned i;for(i=0;i<6;i++){s->voice[i].gate=0;s->voice[i].stage=4;}}
void juno6_render(juno6_t*s,float*out,unsigned n){unsigned k,i;float sr=s->sample_rate;for(k=0;k<n;k++){float mix=0;for(i=0;i<6;i++){juno6_voice_t*v=&s->voice[i];float t,dt,saw,pulse,sub,x,fc,a;if(!v->stage&&v->envelope<.00001f)continue;dt=clampf(v->increment,.000001f,.45f);t=v->phase;saw=2*t-1-blep(t,dt);pulse=t<s->pulse_width?1:-1;pulse+=blep(t,dt);{float q=t-s->pulse_width;if(q<0)q+=1;pulse-=blep(q,dt);}sub=2*fmodf(t*.5f,1)-1;x=saw*.56f+pulse*.34f+sub*s->sub_level;if(s->waveform==1)x=pulse*.72f+sub*s->sub_level;else if(s->waveform==2)x=saw*.82f+sub*s->sub_level;if(v->stage==1){v->envelope+=1/fmaxf(1,s->attack*sr);if(v->envelope>=1){v->envelope=1;v->stage=2;}}else if(v->stage==2){v->envelope-=(1-s->sustain)/fmaxf(1,s->decay*sr);if(v->envelope<=s->sustain){v->envelope=s->sustain;v->stage=3;}}else if(v->stage==4){v->envelope-=fmaxf(.000001f,v->envelope)/fmaxf(1,s->release*sr);if(v->envelope<.00001f){v->envelope=0;v->stage=0;}}fc=clampf(35+powf(s->cutoff,2)*15000+v->envelope*5000,35,sr*.45f);a=1-expf(-TWO_PI*fc/sr);v->filter_state+=a*(x-v->filter_state);v->filter=v->filter_state;mix+=v->velocity*v->envelope*(v->filter*(1+s->resonance*1.4f)-x*s->resonance*.25f);v->phase+=v->increment;if(v->phase>=1)v->phase-=1;}out[k]=mix/6;}}
void juno6_chorus_init(juno6_chorus_t*c,float sr){memset(c,0,sizeof *c);c->sample_rate=sr>8000?sr:44100;c->rate_hz=.8f;c->depth_ms=3.4f;c->mix=.22f;}
void juno6_chorus_set(juno6_chorus_t*c,float r,float d,float m){c->rate_hz=clampf(r,.1f,5);c->depth_ms=clampf(d,1.7f,5.4f);c->mix=clampf(m,0,.5f);}
void juno6_chorus_process(juno6_chorus_t*c,float*l,float*r,unsigned n){unsigned i;float maxd=fminf(255,c->sample_rate*.0054f);for(i=0;i<n;i++){float in=(l[i]+r[i])*.5f,ph=(float)c->phase/4294967296.0f*TWO_PI,d=clampf(c->sample_rate*(c->depth_ms*.001f)*(.5f+.5f*sinf(ph)),1,maxd);unsigned whole=(unsigned)d,a=(c->write+256-whole)&255,b=(a+255)&255;float frac=d-whole,del=((float)c->delay[a]*(1-frac)+(float)c->delay[b]*frac)/32768.0f,wet=del*c->mix;c->delay[c->write]=(int16_t)clampf(in*32767,-32768,32767);c->write=(c->write+1)&255;l[i]=l[i]*(1-c->mix)+wet;r[i]=r[i]*(1-c->mix)-wet;c->phase+=(uint32_t)(c->rate_hz*4294967296.0f/c->sample_rate);}}
